INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Алоқамони муҳим байни обкорӣ ва саломатии гиҳи юнҷа</h2>\n<p>Юнҷа (Alfalfa), ки яке аз арзишмандтарин хӯрокҳои хушк ва този дар саноати чорводорӣ ҳисоб меравад, ба идоракунии дақиқи захираҳои об ва ғизо ниёз дорад. Бисёр деҳқонҳо танҳо омилҳои ирсоӣ ё кимиёvierро сабаби асосии саломатии гиҳ медонанд, ҳоле ки <strong>усули обкорӣ</strong> нақши бевоситаро дар эҷод ё пешгирии заминаи мусоид барои пайдоиши зараранокҳо ва бемориҳои занболагии ва бактерияӣ иҷро мекунанд. Вақте ки намии сатҳи хок ва заминаи гиҳ боз ҳам дар сатҳи баланд бошад, муҳити идеалӣ барои татбиқи занболаҳои зард ва сиёҳ ва ҳатто вайроншавии пойи сабки тавассути бактерияҳо ба вуҷуд меояд. Ин раванд на танҳо ба камшавии ҳосилнокии баланди хӯрок мерасонад, балки муқовимати системаи иммунии гиҳро нисбат ба дигар стрессҳои муҳити, аз ҷумла камбудии хӯрок ва гармии, суст мекунад. Бинобар ин, диққат ба зараранокҳо ва бемориҳои юнҷа аз сабабҳои механикӣ ва физикӣ оғоз меёбад, ки решаҳои онҳо дар интихоби системаи обкорӣ мебошад.</p>\n<p>Системаҳои муосир, аз қабили навори чӯмдакӣ (drip), бо ҷамъ овардани намӣ дар минтақаи решаҳо ва нигоҳ доштани заминаи гиҳ хушк, метавонанд стратегияи муқовимати қавиро муқобил ба бисёр мушкилоти санитарии юнҷа ташкил диҳанд. Дар ин ҷо мо тафсилоти техникии ин давроро меомалим, то фаҳмем, ки чӣ гуна бо як тағйири хурд дар заминаҳои обкорӣ, хароҷотҳои назорати зараранокҳо ва бемориҳоро ба ҳадди ақал расонида метавонем. Ин равшанӣ ҳамзамон бо принсипҳое мувофиқат дорад, ки дар <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%a7%d8%b3%d9%81%d9%86%d8%a7%d8%ac-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">миқдори ҳосили сабзии спанях дар гектар</a> мубҳас шудаанд, зеро ҳарду гиҳ ҳассосияти баланд ба идоракунии намии маҳаллӣ доранд ва стрессҳое, ки аз обкории нодуруст бармеоянд, ба таври бевосита ба муқоисарави табдили нитроген ва сифати ниҳоии маҳсулот таъсир мерасонанд.</p>\n\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-یونجه-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های یونجه با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation юнҷа</figcaption></figure>\n\n<h2>Таъсири бевоситаи обкории чӯмдакӣ (drip) ба камшавии намии маҳаллӣ (Microclimate)</h2>\n<h3>Назорати намии нисбии заминаи гиҳ</h3>\n<p>Яке аз муҳимтарин омилҳои зидди бемориҳои занболагии дар юнҷа намии баланд дар заминаи пӯшиши гиҳ (Canopy) мебошад. Дар обкории пешфишонӣ, тамоми сатҳи барг ва сабки нам доранд ва занболаҳо фурсати пайдоиши спорҳоро меёбанд. Аммо дар системаи навори чӯмдакӣ (drip), об танҳо дар навори дароз ва танн дорудар поёни баргҳо ҷойгир мешавад ва қисми болоии сабки хушк мемонад. Ин масъала меъёри намии сабки (Wetness Duration)-ро ба таври назаррас коҳиш медиҳад, ки сабаби асосии пешгирии дотҳои мисини ва равғани сиёҳ дар юнҷа аст. Коҳиш додани давомнокии намии баргҳо бевосита бо камшавии суръати паҳншавии бемориҳои дотмонанди ҳамроҳ аст. Ин ҷуҳур хуб ифода мекунад, ки идоракунии зараранокҳо ва бемориҳои юнҷа аз назорати намӣ оғоз меёбад. Дар ин самт, фаҳмиши амиқтар аз рафтори об дар матни хок, муҳимияти ду баробар дорад. Ҳамон тавр, ки дар мақолаи шароити обкории электрикӣ шарҳ дода шудааст, устувории потенциали обии хок муайянкунаандаи асосии суръати ҷаббиш ва бухоршавӣ аст. Агар ин параметрҳо дар майдони юнҷа ҳисоб карда нашаванд, хавфи сироятшавии иквонӣ бо занболаҳои хокзистанда, аз қабили Fitofotora, ба таври ошкоро меафзояд.</p>\n<h3>Тақсимоти баробари намӣ дар ҷойҳои решагирӣ</h3>\n<p>Чӯмдакҳои хурд дар навори чӯмдакӣ имкони назорати дақиқтарро таъмин мекунанд. Ҷойҳои решагирӣ ҳамеша дар марзи қобилияти оби хок (Field Capacity) нигоҳ дошта мешаванд. Ин ҳолат барои юнҷа идеалӣ аст, зеро стресси сурхшавии намӣ боиси афзоиши муқовимати физиологиии гиҳ муқобил ба ҳуҷуми паразитҳо мегардад. Ғайр аз ин, пешгирии ҷамъшавии намакӣ дар сатҳи хок (ки дар обкории чуҳҳо шиор аст), аз таҷзияи пешинаи ҷойҳои решагирӣ ва воридшавии бактерияҳои заифкунанда дар намондан аст. Инчунин, хонамдории беҳтари решаҳо дар натиҷаи камшавии сироят, ҷабби бештари моддаҳои минералӣ ва рушди қавитарро кафолат мекунад. Ин раванд, равшанкунии амалиётӣро бо принсипҳое, ки дар <a href="https://navar-abyari.ir/potato-drip-tape-complete-guide/">раҳнамоии пурраи навори чӯмдакӣ барои тухми хӯроквор</a> ора оварда шудаанд, мегирандад; ҷое ки ҳампушитании наворҳо ва пешгирии хушкшавии маҳаллӣ, калиди устувории пухтанши гиҳ аст. Дар юнҷа низ нигоҳ доштани мувозинат байни намӣ ва хушкӣ, аз шикастҳои решагӣ, ки метавонанд дарвозаи воридшавӣ барои нематодаҳои зараровар бошанд, пешгирӣ мекунад.</p>\n\n<h2>Идоракунии зараранокҳо тавассути назорати замина</h2>\n<h3>Кам кардани шумораи ҳашаротҳои гиҳхӯрокӣ</h3>\n<p>Гарди чумак (alfalfa), монанд кариҳои сурхи ва шитоби ҷисмро тоза кардан, аз муҳитҳои намноки баланд ва пошони шаҳбодии зич ба сбаби ноомуқебияти намдорӣ бештар эҳтиром доранд. Бо ислоҳи намунаи ороғубарӣ ба сарати нафас кардан, зичии ишораҳои рушди беҳтар мешавад. Вақте ки решаҳои нишинҳо бо якхелӣ рӯи омадаанд, фазои иловагӣ роҳро барои истиқомати тухоии hashara кӯмак мекунад. Даромади дурусти ин зичӣ ва чандӣ монанди принсипҳое аст, ки дар мавзӯи миқдори бехи нуҳут дар гектар барои гиёҳи шаҳбодии монанд таҳия шудааст, ки дар он намунаи боргузорӣ ва ороғубарии дақиқ нақши асосӣ дар саломати гиёҳ ичро мекунад. Аммо дар чумак, назорати намдорӣ бевосита бо кам кардани шумораи кариҳои хокӣ тавассути хушкии сатҳӣ вобаста аст. Ин диди сабабу натиҷа нишон медиҳад, ки идоракунии муҳитии мутобиқатшаванда, ивазкори мувофиқ барои пуркунии пайдарпаи кимиёвӣ аст. Нуқтаи муҳим ин аст, ки хушкии сатҳӣ суръати ҳаракати hasharaи зарафанишуда-нишинро ҳам кам мекунад, чунки онҳо барои таъминкунӣ ба лӯлаҳои рӯи обӣ ниёз доранд, ки дар шароити хушки сатҳӣ камбуди дастрасӣ пайдо мекунанд.</p>\n<h3>Пешгирии вирусҳои интиқоли тавассути hashara</h3>\n<p>Баъзе бемориҳои вирусии чумак тавассути jukeҳо ва шитоби интиқол медиҳанд. Кам кардани шумораи ин hashara бо идоракунии бозори шаҳбодии зери бунёд, ба таври бевосита хавфи вирусро ҳам кам мекунад. Боз, кам кардани намнокии минималӣ боиси шудани шароити мутобиқатшавандаи қарзҳо, ки аксаран ҳамчун миёнаҳои беморӣ амал мекунанд, мумкин нест. Бо кам кардани шумораи ҳоми hashara, истифодаи моддаҳои химёвӣ аз ҷиҳати иқтисодӣ ва экологӣ кам мешавад, ки дар давоми муддати дароз ба ҳифзи тадбӣи биёи саҳро кӯмак мекунад. Аз ҳамин сабаб, пешгирии гарди ва бемориҳои чумак ниёз ба назари умумӣ ба экосистемаи саҳро доранд. Ин рӯйгардии якҷояшаванда бо мафхуми... <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%b1%d8%b2%d9%85%d8%a7%d8%b1%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори кам кардани ржмари дар гектар</a> мукяб шудааст; ки дар он кам кардани бемориҳои қарзӣ ба зиёд шудани бевоситаи коэффициентҳои камшавандаи фурошанда мусоидат мекунад. Дар чумак ҳам, ҳар маротиба, ки як ҳалқаи беморӣ назорат шавад, давомнокӣ ва такроршавии кам кардан (Regrowth) сахт беҳтар мешавад.</p>\n\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-یونجه-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های یونجه با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation чумак</figcaption></figure>\n\n<h2>Нуқтаҳои амалӣ барои якҷоякунии ороғубарӣ ва идоракунии саломатӣ</h2>\n<ul>\n<li><strong>Интихоби чашеи мувофиқи нуҳаи типӣ:</strong> Барои чумак, ки ба ороғубарии баланд нияз дорад, истифодаи нуҳаҳои бо ришки хурдиштар (масалан, 1.6 миллиметр) барои пошони шаҳбодии зич тавсия дода мешавад, то аз хушкии маҳаллии решаҳои нишинҳо пешгирӣ карда шавад, бе илова намдохтани намнокии зери бунёд. Роишҳони пурра дар мақолаи ҳамаи чизҳо дар бораи судбурҳои нуҳаҳои тири кадар ба тафсилотҳои ришки ришкҳо ишора мекунад, ки принсипҳои онро барои ҳамаи намуди боғҳо низ умумӣ кардан мумкин аст. Интихоби намуди ҷинси лӯлаҳо ва дараҷаи инфилобпазирӣ низ дар давомнокӣи система ва пешгирии дурахшӣ нақши муҳим дорад. Дар минтақаҳои бо оби сахт, истифодаи филтрҳои сикунӣ зарур аст.</li>\n<li><strong>Вақтгузории ороғубарӣ:</strong> Ороғубариро дар сатҳҳои хунҷури шабуниш анҷом диҳед, то бо кам шудани суръати пуршавӣ, ношавии намдорӣ ба зери бунёд камтар бошад ва гиёҳ бо дақиқӣ ҷабишавиро иҷро кунад. Ин корро бештар ришки қарзҳои фаргозиро кам мекунад. Истифодаи таймерҳои зеҳнӣ метавонад дақиқии ин вақтгузориро ба баландӣ расонад ва аз бозгашти оби иловагӣ пешгирӣ кунад. Вақтгузории ороғубарӣ бо барномаи нақли кам кардан, ба таҳаммули кам шудани баргуно дар ҳоми ҷамъоварӣ пайваст нест.</li>\n<li><strong>Ҳалқаҳои ороғубарӣ (Cycle and Pivot):</strong> Ба ҷои ороғубарии милҳавӣ, аз системаи ҳалқаӣ истифода баред, ки дар он қисм аз каналҳо дар вақтҳои мушаххас ороғубарӣ шаванд. Ин ҳалқа аз ҷамъшавии доими намдорӣ дар як нуҳаи барики пешгирӣ мекунад ва монеаи рушди решаҳои нишини беморизои он нуҳаи хос мешавад. Ин роҳ тавассути умумӣ барои беҳтар шудани рушди пошони шаҳбодии шаҳбодӣ дар тамоми соҳаи саҳро боис мегардад. Идоракунии гидравликии монанд, ба принсипҳое монанд аст, ки дар... <a href="https://navar-abyari.ir/miqdori-daromadi-zurati-meksikii-dar-hektar/">Миқдори даромади деҳқонони мексикӣ дар гектар</a> барои беҳтар кардани иқтисодии самаранокӣ муҳим аст; зеро бозгашти иловагии об бевосита аз баҳодиҳии деҳқон кам мекунад.</li>\n<li><strong>Нозоруати шаҳмӣ:</strong> Гарчанде ки набуни бунбаҳорӣ намакиро ба канори наби марказӣ равона мекунад, дар хокҳои намакдор бояд аз масофаи мувофиқи набиҳо аз сафтунони растаниҳо боварӣ ҳосил кунед. Намаки зиёд дар ҷойҳои рушди рӯидаҳо растаниро дар фанорӣ мебарад ва онро ба таҳаммулӣ бар зидди бемориҳо мекунад. Ҷараёни мунтазами EC дар об ва хок барои пешгирӣ аз ҷамъшавии намак дар рӯидаҳо зарурӣ аст. Инчунин, диққат ба <a href="https://navar-abyari.ir/string-bean-yield-per-hectare-factors-increase/">омилҳои зиёдшавии ҳосили нони сабз дар гектар</a> мумкин аст намунае бошад, дар ҷое, ки идоракунии намакӣ ва танзими pH суръати табдили об ба бутаро зиёд мекунад ва хатарро коҳиш медиҳад.</li>\n</ul>\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<h3>Оё обёрӣи бунбаҳорӣ тоҷиди бемориҳои вирёсиро давоми мекунад?</h3>\n<p>Не. Обёрӣи бунбаҳорӣ як асбоби пешгирӣ ва идоракунии оҳан аст, на давоми бевоситаи вирёсӣ. Аммо бо коҳиши шумораи ҳашароти василакунанда ва зиёдшавии устувории физиологӣи растани, сатҳи паҳншавӣ-ро ба таври назаррас коҳиш медиҳад. Давоми вирёсиҳо талабгарии интихоби шаклҳои муқовиматнок ва идоракунии ягонаи зараррасонҳост, аммо обёрӣи дақиқ заминаи солимтарини саҳро-ро фароҳам меорад. Бинобар ин, идоракунии зараррасонҳо ва бемориҳои лӯбиё раванди пайдарпайдост, ки назорати доимӣ бар нишондиҳандаҳои саломатии растаниро талаб мекунад.</p>\n\n<h3>Оё истифодаи наби бунбаҳорӣ дар саҳроҳои лӯбиёи бисёрсола масъала-ро ба вуҷуд меорад?</h3>\n<p>Агар набиҳо сатҳӣ ҷойгир шуда бошанд, дар солҳои дуюм ва сеюм, ки ҷангоҳҳо васеъ мешаванд, набиҳо метавонанд зери фишори механикӣ қарор гирянд. Тавсия мешавад, ки дар марҳилаи кабуд, набиҳоро каме поёнтар (Sub-surface) бо рафъи мувофиқ сурат диҳед ё набиҳои балпайдарпайро бо умри дарозтар истифода баред. ҳисобҳои дақиқи анҷоми ҳаракатҳои нигоҳдорӣ, калиди таъмини иқтисодии ин системаҳо аст ва бояд дар ҷанбаи мавзӯи зараррасонҳо ва бемориҳои лӯбиё ба назар гирифта шавад. Ӯмри системаи обёрӣ мустақиман бо муқовиматаш ба UV ва таҳмирӯи механикӣ аз ҷонҷӯлҳои ҷамъбурд вобаста аст.</p>\n\n<h3>Беҳтарин масофаи хатар барои лӯбиё чӣ қадар аст?</h3>\n<p>Одатан, масофаҳои 20 то 30 сантиметр байни набиҳо дар наби бунбаҳорӣ 16 ё 20 миллиметр барои фарогирии пурраи рӯидаҳои лӯбиё мувофиқ аст, аммо ин ба зичии кабуд ва намуди хок вобаста аст. Дар хокҳои балғӣ, масофаҳои кӯтоҳтар тавсия мешаванд, то пеш аз хушкшавии маҳаллӣ пешгирӣ карда шавад. Танзими дақиқи рафъ бояд <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d9%86%d8%ae%d9%88%d8%af-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">миқдори ток лӯбиё дар гектар</a> ва принсипҳои шабеҳи он дар дигар растанҳои данавӣ мутаносиб гардонида шавад, то пеш аз фарогирии нафаъол ва хушкшавии канорӣ пешгирӣ карда шавад.</p>\n\n<h2>Хулоса ва тавсияҳои ниҳоӣ</h2>\n<p>Идоракунии зараррасонҳо ва бемориҳои лӯбиё як равиши якбуни нест; балки комбинатсияи интихоби шаклҳои муқовиматнок, ғизокунии мувозинатнок ва <strong>обёрӣи Ӯммонӣ</strong> аст. Системаҳои бунбаҳорӣ ва наби бунбаҳорӣ бо фароҳам овардани имконияти идоракунии дақиқи намнокӣ, силои қавитарин дар дасти соҳибкор бар зиддии бемориҳои занбӯруқӣ ва коҳиши фишори физиологӣ мебошад. Бо ӯрда ба додаҳои илмӣ ва принсипҳои техникӣ, ки дар манбаҳои гуногун муҳокам шудаанд, мо метавонем ба маҳсулоти устувортар ва солимтар даст ёбем. Сармоягузорӣ дар зери сохторҳои обёрӣи дақиқ, на танҳо дар ҳосил, балки дар умри иқтисодии саҳро низ барориши сармоя дорад. Соҳибкорон бояд бидонанд, ки ҳар қатраи оби таъминшуда ё дуруст истифодашуда сармоое барои саломатии ояндаи маҳсулоти онҳо аст.</p>\n\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-یونجه-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های یونجه با آبیاری قطره‌ای - تصویر 3"/><figcaption>зараррасонҳои бемориҳои растаниҳо обёрӣи бунбаҳорӣ лӯбиё</figcaption></figure>','Мудирияти зараррасонҳо ва бемориҳои ҷўй барои обёрӣи дақиқ','Учунчӯрачӣ ҳамчун бунёдтарин комӣ лозимидириб дошт. Дар ин матале мо таҳлил мекунем, ки чӣ тавр зараррасонҳо ва бемориҳои учунчӯрачӣ-ро бо беҳтар кардани системаҳои обёрӣ қатрагӣ ва назорати намноки замин ва пардаи ҷисмоӣ кам кардан мумкин аст.','publish','closed','closed','zararzonho-va-bemoriho-joyoy-abori-daghiq',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
