INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='tj' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>القمح أحد الأعمدة الرئيسية للأمن الغذائي العالمي، وهو محصول يُزرع في العديد من المناخات. مع انتقال المزارعين نحو أنظمة الري الدقيقة، مثل الري بالتنقيط والخطوط الريشية، تغيرت المعايير الفسيولوجية للنبات وأنماط أمراضه تغيرات عميقة. وعلى الرغم من أن هذه الطرق تعظم كفاءة استخدام المياه وتقلل تكاليف الزراعة الجارية، فإنها تجعل إدارة الآفات والأمراض أكثر تعقيداً وحساسية. في هذا الدليل، ستتعرف بالتفصيل على التحديات الخاصة بالقمح في حالات ارتفاع رطوبة منطقة الجذور، والتعفنات الفطرية، والآفات الحشرية التي تتأثر بنظام الري، وتتعلّم حلولاً عملية للتعامل معها.</p>\n\n<h2>أثر الري بالتنقيط على انتشار أمراض القمح</h2>\n<p>في نظام الري بالتنقيط، تتراكم الرطوبة بشكل مركّز ومباشر في منطقة الجذور (Root Zone) وحول خطوط التنقيط. وعلى الرغم من أن تركيز الرطوبة هذا مفيد لامتصاص أقصى للمغذيات من قبل النبات، إلا أنه من منظور الأمراض النباتية، يخلق بيئة مثالية وغير مرغوبة للفطريات المدمرة مثل <strong>تعفن الجذور</strong> و <strong>تعفن العنق</strong> تخلق هذه الفطريات بيئة مثالية وغير مرغوبة في التربة التي تبقى رطبة باستمرار ونقص التهوية المناسب، حيث يزيد نشاطها الإنزيمي وتتسارع في اختراق أنسجة النبات. ومن ناحية أخرى، يمكن أن تقلل طريقة الري بالخطوط الريشية من هذا الخطر بفضل توزيع أكثر انتظاماً للمياه على طول الخط، بشرط أن يكون نظام تصريف التربة مناسباً. كما أن عدم التوازن في امتصاص الماء والعناصر الغذائية، الذي قد يحدث أحياناً بسبب انسداد خطوط الري، يسبب ضعفاً في البنية الجدارية الخلوية للنبات، مما يجعله أكثر عرضة لغزو الآفات الحشرية والفطرية.</p>\n\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-گندم-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های گندم با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation گندم</figcaption></figure>\n\n<h3>تعفن الجذور والعنق في خطوط الري</h3>\n<p>الفطريات التابعة للجنس <em>Fusarium</em> (فوزاريوم) و <em>Rhizoctonia</em> (ريزوكتونيوم) تُعتبر الأعداء الرئيسيين للقمح في أنظمة الري الدائمة وشبه الدائمة. وتصبح هذه مسببات الأمراض نشطة جداً في التربة التي تحافظ على تشبعها بالرطوبة وقليلة الأكسجين. وتشمل الأعراض الأولية لهذه الأمراض اصفرار الأوراق السفلية، والذبول السريع في الفترات التي تكون فيها رطوبة التربة مرتفعة جداً، وباهت السيقان، وفي النهاية موت النبات من الجذر. في هذه الحالة، يكون استخدام أساس مناسب بحبيبات كبيرة وتسييل اصطناعي أمراً حيوياً. ويمكن أن يساعد فهم المبادئ التقنية وتدريب الاستخدام الصحيح للخطوط الريشية في منع خلق مناطق تصريف ضعيفة وتراكم مسببات الأمراض في نقطة معينة. كما أن الحفاظ على مسافة مناسبة بين الخطوط لتهوية التربة بشكل جيد حول الجذور ضروري.</p>\n\n<h2>الآفات الحشرية في القمح تحت الري بالتنقيط</h2>\n<p>الآفات الحشرية للقمح، ومن بينها <strong>الذبابة البيضاء</strong>، <strong>الحربائش</strong> والعث الزيتي، غالباً ما تجد نمواً وتكاكراً أكبر في ظروف البرودة والرطوبة العالية. يمكن لأنظمة الري بالتنقيط أن تجعل الظروف أكثر ملاءمة لبعض الحشرات الخيطية أو الرطبة من خلال خفض حرارة سطح التربة ورفع الرطوبة النسبية في المناخ المجهري حول النبات. ومع ذلك، فإن ضعف النبات الناتج عن نقص التغذية، والذي قد يكون بسبب تركيز غير كافٍ للمحلول الغذائي في التنقيط، يؤدي إلى تقليل جهاز المناعة النباتي وزيادة جذب الحشرات الماصة للعصارة. هذه الحشرات، عن طريق مصّ عصارة النبات، لا تدمّر العناصر الغذائية فحسب، بل تنقل أيضاً فيروسات مختلفة إلى النبات، مما يجعل إدارتها أصعب بكثير.</p>\n\n<h3>الذبابة الخيطية (المن) والصدأ: الإدارة المتكاملة</h3>\n<p>الذبابة الخيطية (المن) في القمح، عن طريق إفراز العصارة النباتية الحلوة (الإفرازات اللزجة)، تسبب ظهور العفن الأسود (Sooty mold) ونمو الفطريات ذات اللون الأصفر على الأوراق. تقوم هذه الفطريات بإعاقة عملية التمثيل الضوئي، وتقلل بشدة من إنتاج المحصول. تتطلب إدارة الآفات المتكاملة (IPM) مراقبة بصرية منتظمة ومراقبة دقيقة لنطاقات الري لضمان عدم احتواء أماكن وضع البيض للذبابة الخيطية (المن). عند ملاحظة الأعراض، فإن استخدام المبيدات الحيوية مثل <em>Bacillus thuringiensis</em> أو تعزيز المفترسات الطبيعية مثل الدبابير والخنافس المفترسة، يسبب أقل ضرر للبيئة ونظام الري، ويحافظ على التوازن البيئي للمزرعة. كما يساعد في تقليل ضغط الآفات ضبط الأعشاب الحشائش (Weeds) التي تعمل كمضيفات للذبابة الخيطية (المن).</p>\n\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-گندم-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های گندم با آبیاری قطره‌ای - تصویر 2"/><figcaption>آفات وأمراض المحاصيل الري بالتنقيط القمح</figcaption></figure>\n\n<h3>الصدأ البني والصدأ الأصفر: التشخيص والمواجهة</h3>\n<p>الصدأ من أكثر الآفات شيوعاً وتدميراً في القمح في المناطق الرطبة والمحاصيل الكثيفة. يصيب الصدأ الأصفر (Yellow Rust) عادةً في أوائل موسم النمو مع الطقس البارد والضبابي، بينما يصبح الصدأ البني (Brown Rust) أكثر نشاطاً في منتصف الموسم مع درجات الحرارة المرتفعة والرطوبة المناسبة. في الري بالتنقيط، على الرغم من أن الرطوبة المباشرة على سطح الأوراق (Foliage) أقل، إلا أن الرطوبة العالية للتربة تسبب نمواً أقوى لجذور النبات، وبالتالي إنتاج المزيد من المواد الغذائية والطاقة للنبات؛ وإذا لم يكن التوازن موجوداً، فإن هذا يعد مريخاً مناسباً للمهاجمين (المرضي) النازلة للنظام. المراقبة الدقيقة لنطاقات الري للتعليد المبكر على بقع الصدأ، التي تبدأ من طرف الأوراق، ضرورية وتسمح للمزرعة باتخاذ إجراءات تصحيحية قبل انتشار المرض.</p>\n\n<h2>نصائح عملية للوقاية والتحكم</h2>\n<p>للحصول على أقصى عائد وصحة القمح في زراعات النطاقات (rip) أو التنقيط، يوصي بشدة باتباع المبادئ التالية:</p>\n<ol>\n<li><strong>التغذية المتوازنة وقابلية الرش:</strong> استخدام الأشكال السائلة أو القابلة للرش من المواد الغذائية التي تُحقن مباشرة من نطاق الري يمنع سوء التغذية الذي يسبب الإجهاد والحساسية للمهاجيم (الآفات).</li>\n<li><strong>إدارة ذكية للرطوبة:</strong> تصحيح دقيق لإشباع التنقيط أو عرض نطاق التريبي (الرش) لمنع تشبع التربة وتراكم الماء. يمكن أن تساعد رطوبة التربة المستشعرات في توقيت الري للحفاظ على توازن الماء-الهواء في منطقة الجذور.</li>\n<li><strong>دورة المحاصيل والتناوب:</strong> زراعة القمح في نطاقات الري مع محاصيل أقل حساسية للفطريات المشابهة، مثل الشوفان أو التريتيكس، يمكن أن يكسر دورة حياة المهاجمين (المرضي) المستديمة في التربة. يؤدي هذا الإجراء إلى تقليل الحمل الفطري وتقليل الحاجة إلى الرش الكيميائي.</li>\n</ol>\n\n<p>بالإضافة إلى ذلك، فإن اختيار بذور ذات جودة عالية ومقاومة للفطريات أمر بالغ الأهمية. تعمل البذور المقاومة للفطريات على زيادة المقاومة الأولية للنبات ضد داء الحبوب (الذبول). لتحديد الكثافة المناسبة للبذور في نطاقات الري التي تؤثر على تهوية التربة وتقليل مخاطر المهاجين (الآفات)، يمكنك الاستعانة بجدول الدليل لـ <a href="https://navar-abyari.ir/triticale-seed-per-hectare-density-table/">كثافة بذور التريتيكس في الهكتار</a> لأن المبادئ المشابهة تنطبق على الحبوب وإدارة مسافات الزراعة. معرفة حجم محصول الشمندر في الهكتار كمؤشر اقتصادي يساعدك على تقدير العائد المتوقع للقمح أيضاً.</p>\n\n<h2>الأسئلة الشائعة (FAQ)</h2>\n<h3>هل يسبب الري بالتنقيط بشكل مباشر إلى زيادة حشرة المن على القمح؟</h3>\n<p>لا بشكل مباشر، لكن زيادة رطوبة التربة قد تؤدي إلى نمو أسرع للنباتات الغريبة والأعشاب التي تكون مضيفاً للمان. بالإضافة إلى ذلك، يُضعف نقص التغذية أو الإجهاد الناتج عن نقص الأكسجين في الجذور صحة النبات، مما يجعله هدفًا أكثر جاذبية للحشرات الماصة التي تعطل دفاعات النبات.</p>\n\n<h3>ما هو أفضل وقت للتبخير في شريطات الري؟</h3>\n<p>يجب إجراء التبخر قبل ذروة محصول الفطريات وعند ملاحظة أعراض اصفرار أو بقع بنية. في الأنظمة التنقيطية، من الأفضل استخدام مبيدات فطرية قابلة للذوبان في الماء لضمان وصولها من خلال الشريط إلى التربة. قد يؤدي تداخل المواد الكيميائية مع ماء الري إلى زيادة مخاطر تلوث مصادر المياه، لذا يجب الالتزام بفارق زمني مناسب بين الري والتبخير.</p>\n\n<h3>هل شريط تيبي أفضل من التنقيط في السيطرة على تعفن الجذور؟</h3>\n<p>نعم، يوفر شريط تيبي توزيعاً أكثر انتظاماً للرطوبة ومنعاً لتجمع المياه في نقطة صغيرة، وهو الآلية الرئيسية لتعفنات البكتيريا والفطريات. للاطلاع على التفاصيل الهيكلية واختيار السد المناسب الذي يقلل التسرب إلى الحد الأدنى، راجع <a href="https://navar-abyari.ir/%d8%b6%d8%ae%d8%a7%d9%85%d8%aa-%d8%a7%db%8c%d8%af%d8%b9%d8%a7%d9%84-%d8%ac%d8%af%d8%a7%d8%b1%d9%87-%d9%86%d9%88%d8%a7%d8%b1-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%aa%db%8c%d9%be-2/">سُمك الجدار المثالي لشريط الري تيبي</a> للقراءة. يؤثر اختيار السماكة المناسبة بشكل مباشر على عمر الشريط واستقرار الري.</p>\n\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-گندم-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های گندم با آبیاری قطره‌ای - تصویر 3"/><figcaption>crop pests diseases drip irrigation غندم</figcaption></figure>\n\n<h2>الملخص والتوصيات النهائية</h2>\n<p>يتطلب إدارة الآفات والأمراض في القمح ضمن أنظمة الري الدقيقة نظرة شاملة ومتعددة الأبعاد. الرطوبة، رغم ضرورتها للقمح، يمكن أن تتحول إلى عامل لتفشي المسببات المرضية في التربة والهواء. من خلال تطبيق مبادئ التصريف الجيد، واختيار بذور سليمة ومقاومة، والمراقبة المستمرة لشريطات الري، يمكن منع انخفاض العائد وتلف المحصول. تكامل نظام الري مع التغذية الدقيقة ومكافحة الآفات هو المفتاح لتحقيق عائد مستقر وجودة عالية. يُنصح المزارعون بالتخطيط لإدارة النفايات ودورة المحاصيل بشكل متزامن مع تصميم النظام للحفاظ على صحة بيئة شريطات الري. كما أن الإلمام بكيفية تحديد نقاط الري لشريط تيبي بشكل صحيح يمكن أن يمنع التشبع وتجمع الرطوبة في النقاط العمياء ويقلل من مخاطر الأمراض.</p>\n<p><strong>مواضيع ذات صلة:</strong> معدل حصاد البصل الأخضر للفدان: دليل شامل + نصائح للزيادة، دليل شامل لزرع القرع</p>\n<p><strong>مواضيع ذات صلة:</strong> <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%DA%86%D8%A7%D9%88%D8%AF%D8%A7%D8%B1-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA DA86D8A7D988D8AFD8A7D8B1 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>، <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d9%be%db%8c%d8%a7%d8%b2%da%86%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">معدل حصاد البصل الأخضر للفدان: دليل شامل + نصائح للزيادة</a></p>','آفات و بیماری‌های گندم با آبیاری قطره‌ای: راهنمای جامع کنترل و پیشگیری','يتعرض القمح في أنظمة الري بالتنقيط وشريط التنقيط لتحديات فريدة من نوعها عند مواجهته مسببات الأمراض والحشرات. تتناول هذه المقالة دراسة آليات تفشي الأمراض تحت ظروف الرطوبة المحلية المرتفعة، وتقديم حلول متكاملة لإدارة الأضرار بشكل مستدام.','publish','closed','closed','wheat-pests-diseases-drip-irrigation-guide-afp',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
