INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Гудум яке аз асосҳои бешубҳаи амнияти озуваи ҷаҳонӣ ва як гуна заҳроба аст, ки дар бисёр иқлимҳо парвариш карда мешавад. Бо гузаштани деҳқонон ба сӯи системаҳои ормои дақиқ, ба монанди қатрагӣ ва шинарипӣ, параметрҳои физиологӣи баргил ва намунаи пафологияи он тағйиротҳои амиқро меҳарзанд. Гарчанде ин усулҳо самаранокии обро ба максимум мерасонанд ва хароҷотҳои ҷориро кам мекунанд, вале идоракунии зараранҷумҳо ва бемориҳоро мураккабтар ва ҳассостар менамояд. Дар ин дастурамал, бо одашҳои махсуси гудум дар шароити намӣи баланди минтақаи решаҳо, гиряҳгӯиҳои зумуриашо ва зараранҷумҳои ҳашарӣ, ки зери таъсири системаи ормо будаанд, тафсилотан шинос мешавед ва роҳҳои амалӣ барои муқобила бо онҳоро меомӯзед.</p>\n\n<h2>Таъсири ормои қатрагӣ ба паҳншавии бемориҳои гудум</h2>\n<p>Дар системаи ормои қатрагӣ, намӣ бо шакли марказӣ ва мустақим дар минтақаи решаҳо (Root Zone) ва атрофи лӯлаҳои қатрагӣ ҷамъ мешавад. Гарчанде ин консентратсияи намӣ барои ҷамъоварии максимумӣи моддаҳои ғизоӣ бо тавассути баргил сарфақанд аст, вале аз нигоҳи пафология барои зумуриашоҳои вайронкунанда чунин <strong>гиряҳгӯии решаҳо</strong> ва <strong>гиряҳгӯии лӯлаи (столб)</strong> муҳити идиолӣ ва манфид эҷод мекунад. Ин зумуриашоҳо дар хок, ки доимо тоза ва бе ҳавогирии мувофиқ бошад, фаъолияти энзимии зиёдатар доранд ва ба уфури баргилоф илова мешаванд. Дар ҳоле ки, усули шинарипӣ бо сабаби тақсимоти баробартари об дар тӯли шинарипӣ метавонад ин хатарро кам кунад, шарт бар он ки системаи оббарориши хок мувофиқ бошад. Нокоҳиш дар ҷамъоварии об ва моддаҳои ғизоӣ, ки баъзан ба сабаби пӯшидан шинарипҳои ормо рух медиҳад, заифии сохторӣ дар девори ҳуҷайраи баргил эҷод менамояд ва онро дар назди зарар анҷумҳои ҳашарӣ ва зумуриашоҳо бешубҳа менамояд.</p>\n\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-گندم-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های گندم با آبیاری قطره‌ای - تصویر 1"/><figcaption>zararonjumho bemorihom ormoqatragii gandum</figcaption></figure>\n\n<h3>Гиряҳгӯии решаҳо ва лӯлаҳо дар шинарипҳои ормо</h3>\n<p>Зумуриашоҳои ба ҷинси тааллуқ доранда <em>Fusarium</em> (Фозарийум) ва <em>Rhizoctonia</em> (Ризококтониум) душманони асосии гудум дар системаҳои ормои дамодавӣ ва нимдамодавӣ ҳисоб мешаванд. Ин пафогенҳо дар хок, ки намии сатурашашро нигоҳ медорад ва оксиген маҳдуд аст, хеле фаъол мегарданд. Аломатҳои ибтидоии ин бемориҳо аз ҷумла ранги зарди баргҳои поёнӣ, бозшавии тез дамоҳе, ки намии хок хеле баланд аст, сурхагии тирӯк ва дар ниҳоят марги баргил аз реша аст. Дар ин ҳолат, истинодани бинки мувофиқ бо дараи калон ва оббарориши сунъӣ муҳим аст. Ошноӣ бо асосҳои техникаӣ ва омӯзиши истинодани дуруст шинарипӣ метавонад аз эҷоди зонҳои оббарориши заиф ва ҷамъшавии пафогенҳо дар як нуқтаи муайян пешгирӣ кунад. Инчунин, риояи масофаи мувофиқ байни шинарипҳо барои эҷоди ҳавогирии мувофиқи хок дар атрофи решаҳо зарур аст.</p>\n\n<h2>Зараранҷумҳои ҳашарӣ дар гудум зери ормои қатрагӣ</h2>\n<p>Зараранҷумҳои ҳашарии гудум, аз ҷумла <strong>шипшуки гудум</strong>, <strong>қорпӯш</strong> ва гургҳои рӯғноӣ, дар шароити хунукӣ ва намии баланд одатан афзоиш ва насли зиёте меёбанд. Системаҳои ормои қатрагӣ метавонанд бо кам кардани ҳарорати сатҳи хок ва зиёд кардани намии нисбӣ дар микроклими атрофи баргил шароитҳоро барои баъзе ҳашарҳои офтобдӯз ё намакдӯз мусоидтар созанд. Бо вуҷуди ин, заифии баргил аз сабаби камбудии ғизо, ки метавонад ба сабаби тағъири ғайрикофии маҳлулҳои ғизоӣ дар қатрагӣ ба вуҷуд ояд, боиси паст шудани системаи муҳофизати баргил шуда ва ҷозибаи бештари ҳашарҳои мехунданиро дар бар мегирад. Ин ҳашарҳо бо мехундани ширчаи баргил, ғайр аз нест кардани моддаҳои ғизоӣ, вирусҳои гуногунро низ ба баргилоф интиқол медиҳанд, ки идоракуниашоҳоро хеле мураккабтар менамояд.</p>\n\n<h3>Шафрон ва Хурсак: идоракунии интегралишуда</h3>\n<p>Шафрони сафеди гулбӯташ бо ҷараёни шӯreti ғиломӣ (мус) боиси зиреҳпӯшидани баргҳо ва рӯиши қоричаҳои зардранг (Супиқор) мегардад. Ин қоричаҳо фотосинтезро кам карда, истеҳсоли ғизои бисёрро кам мекунанд. Идоракунии интегралишидаи зарароварон (IPM) ба назорати бинии доимӣ ва дақиқи навиҳои обёрӣ ниёз дорад, то аз пахшадан ҷойи ниҳоли шафрон пешгирӣ шавад. Дар сурати ошкоршудани аломатҳо, истифодаи заҳругунҳои биологӣ ба монанди <em>Bacillus thuringiensis</em> ё дастгирӣ ба шикорчиёни табиӣ ба монанди арахшакҳо ва шаканкаҳо, ҳадди ақал зарарро ба муҳити замин ва системаи обёрӣ мерасонад ва мувозунати экологии бодормонро нигоҳ медорад. Инчунин, назорати гиёҳҳои ҳамроҳ (Оҳушакҳо), ки меҳмон барои шафрон мебошанд, ба коҳиши фишори зарароварон мусоидат мекунад.</p>\n\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-گندم-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های گندم با آبیاری قطره‌ای - تصویر 2"/><figcaption>zararandoroni kitobkunoni zardropiriyi guzubun</figcaption></figure>\n\n<h3>Хурсаки қаҳваранг ва зард: шиносоӣ ва мубориза</h3>\n<p>Хурсакҳо аз ҷумлаи оддӣтарин ва хатарноктарин зарароварони гулбӯташ дар минтоҳои намнок ва куштори зич мебошанд. Хурсаки зард (Yellow Rust) одатан дар оғози фасли рушд ва ҳавои хунук ва туманнок паҳн мешавад, дар ҳоле, ки хурсаки қаҳваранг (Brown Rust) дар миёнаи фасл ва бо ҳарорати баландтар ва намнокӣ мувофиқ фаъолтар мегардад. Дар обёрӣ дар ҳолати қутқаҳ, гарчанде намнокӣи мустақим дар сатҳи баргҳо (Foliage) кам аст, вале намнокӣи баланди замин боиси рӯиши қавитар системаи решаи ва дар натиҷа истеҳсоли моддаҳои ғизоӣ ва энергияи бисёр барои оҳанг мегардад, ки агар мувозунат набошад, меҳмони муносиб барои патогенҳои системӣ ҳисоб мешавад. Назорати дақиқи навиҳои обёрӣ барои шиносоии барвақт биниҳои хурсакӣ, ки дар аввал аз анҷоми баргҳо оғоз меёбанд, зарурӣ аст ва бодормонро имкон медиҳад, ки пеш аз паҳншавии беморӣ чораҳои ислоҳкорӣ анҷом диҳад.</p>\n\n<h2>Нуқтаҳои амалӣ барои пешгирӣ ва назорат</h2>\n<p>Барои расидан ба ҳадди аксар самаранокӣ ва солимӣи гулбӯташ дар куштори навии пайваншда ё қутқаҳӣ, риояи принсипҳои зери ба қатъ тавсия дода мешавад:</p>\n<ol>\n<li><strong>Тғизои мувозунатбахш ва ҳалшаванда барои спрей:</strong> Истифодаи шаклҳои моеъ ё ҳалшаванда барои спрей аз моддаҳои ғизоӣ, ки мустақиман аз нави обёрӣ ҷорӣ мешаванд, пешгирии камбуди ғизоӣ мекунад, ки заминаи стресс ва ҳассосият ба зарароварон мебошад.</li>\n<li><strong>Идоракунии эҳтиромии намнокӣ:</strong> Танзими дақиқи шиддати ҷараёни қутқаҳӣ ё баррасии нави пайваншда барои пешгирии ҳосилии замин ва ҷамъшавии об. Намнокӣсанҷиҳои замин метавонанд дар тайёривазкунӣи обёрӣ барои нигоҳдошти мувозунати оби-ҳавои зонаи решаи мусоидат кунанд.</li>\n<li><strong>Давраи куштор ва дуборакушторӣ:</strong> Куштори гулбӯташ дар навиҳои обёрӣ бо гиёҳҳои камҳассос ба қоричаҳои монанд, ба монанди шафрон ё таригке, метавонад давраи зиндагии патогенҳои босаҳи дар заминро қатъ кунад. Ин усул боиси коҳиши борони қоричаҳо ва коҳиши зарурати спрейкунии кимиёвӣ мешавад.</li>\n</ol>\n\n<p>Гарчанде ин, интихоби бубаи сифатнок ва муқоиматнок ба қоричаҳо хеле муҳим аст. Бубаи муқоиматнок ба қоричаҳо муқоимати ибтидоии оҳангро ба зиреҳпӯшидани чашмавӣ меафзояд. Барои муайян кардани зичии муносиби буба дар навиҳои обёрӣ, ки ба замин ва коҳиши ризои зарароварон таъсир мерасонад, метавонед ба ҷадвали роҳнамои <a href="https://navar-abyari.ir/triticale-seed-per-hectare-density-table/">Зичии бубаи таригке дар ҳектар</a> муроҷиат кунед, зеро принсипҳои монанд барои зериҳои гулбӯташ ва идоракунии масофаи куштор истифода меёбанд. Дониши миқдори ҳосили шакарӣ дар ҳектар ҳамчун нишондиҳандаи иқтисодӣ ба шумо кӯмак мекунад, ки самаранокии бехуд барои гулбӯташро баҳодиҳӣ кунед.</p>\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<h3>Оё ошқорӣ по қатра (drip) бевосита боиси зиёд шудани афати гандум (шупшак/aphid) мебошад?</h3>\n<p>Бевосита не, аммо зиёд шудани таррамии хок метавонад боиси растании тезтари гиёҳони зараровар ва бӯғӣ (weed) гардад, ки мавҷи (хазна) барои шупшак мебошанд. Илова бар ин, заифии растаи аз камои озуғаварӣ ё стресс аз сабаби камбудии оксиген дар реша онро барои ҳашароти шикорчигар барангезатар менамояд, ки системаи дифоии растаро заиф мекунанд.</p>\n\n<h3>Беҳтарин вақти зарб расидан ба ҳашарот (печинкишавӣ) дар системаҳои ошқорӣ чист?</h3>\n<p>Печинкишавӣ бояд пеш аз қуллаи эҳтимоли сиробӣ бо занбӯруғ ва вақте ки аломатҳои зардӣ ё дағалакҳои қумра мебинед, анҷом дода шавад. Дар системаҳои ошқорӣ по қатра беҳтар аст, ки аз ҳашароткушҳои фазилӣ, ки ба усули маҳлул (Water Soluble) истифода мешаванд, фоида варзед, то тавассути ларза ба позои (пола) расад. Хомӯш шудани моддаҳои отрувӣ бо оби ошқорӣ метавонад хатари заҳрпаҷудии манбаъҳои обро зиёд кунад, бинобар ин бояд фосилаи мувофиқи вақтӣ байни ошқорӣ ва печинкишавӣ риоя шавад.</p>\n\n<h3>Оё системаи ошқории ларзаро (tape) нисбат ба ошқорӣ по қатра дар назорати таркиб (пӯсидан) реша беҳтар аст?</h3>\n<p>Бале, системаи ошқории ларзаро тақсимоти баробартари таррамиро эҷод мекунад ва аз ҷамъшавии марказӣ дар як нуқтаи хурд пешгирӣ мекунад, ки ин механизм асосии пӯсиданҳои бактериявӣ ва занбӯруғиҳо мебошад. Барои ошкории тафсилоти сохторӣ ва интихоби деверӣ (дивар) мувофиқ, ки рағбат (нӯшадан)ро ба ҳадди ақал расонад, бахшро <a href="https://navar-abyari.ir/%d8%b6%d8%ae%d8%a7%d9%85%d8%aa-%d8%a7%db%8c%d8%af%d8%b9%d8%a7%d9%84-%d8%ac%d8%af%d8%a7%d8%b1%d9%87-%d9%86%d9%88%d8%a7%d8%b1-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%aa%db%8c%d9%be-2/">қабати идеалии деверия системаи ошқории ларзаро</a> мӯҳим кунед. Интихоби қабати мувофиқ таъсири бевосита ба умри хизматрасонии ларза ва устувории ошқорӣ дорад.</p>\n\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-گندم-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های گندم با آبیاری قطره‌ای - تصویر 3"/><figcaption>crop pests diseases drip irrigation гандум</figcaption></figure>\n\n<h2>Хулоса ва тавсияҳои ниҳоӣ</h2>\n<p>Идоракунии ҳашарот ва бемориҳои гандум дар системаҳои ошқорӣ дақиқ ба диди макро ва чандбулиӣ ниёз дорад. Тарра, гарчанде ки барои гандум зарур аст, метавонад ба омил барои пароканда шудани патогенҳои хокӣ ва ҳавоӣ табдил ёбад. Бо иҷрои принсипҳои рехкунии зиёдатии об, интихоби тухми солим ва баисоркунанда ва назорати даимии ларзаҳои ошқорӣ, метавон аз кам шудани шикор (ҳосил) ва фурӯ равон шудани маҳсул пешгирӣ кард. Ягонагии системаи ошқорӣ бо озуғаварии дақиқ ва назорати ҳашарот калиди расидан ба ҳосили устувор ва сифати баланд аст. Ба деҳқонон тавсия дода мешавад, ки ҳамзамон бо тарҳрезии система, барномабарорӣ барои идоракунии парҳезонӣ ва давраи гулронии кӯпокиро низ анҷом диҳанд, то солимӣи муҳити зист дар ларзаҳои ошқорӣ ҳифз шавад. Инчунин, шиносӣ бо роҳи муайян кардани нуқтаҳои ошқории ларзаҳои ошқорӣ метавонад аз шилидҳо (еродия) ва ҷамъшавии тарра дар нуқтаҳои ноаён (коёр) пешгирӣ кунад ва хатари бемориҳоро коҳиш диҳад.</p>\n<p><strong>Маводҳои алоқаманд:</strong> Миқдори ҳосили пиёзча дар гектар: Раҳнамои комил + Нуқтаҳои зиёдшавӣ, Раҳнамои комил барои кардани кабботи бумадӣ</p>\n<p><strong>Маводҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%DA%86%D8%A7%D9%88%D8%AF%D8%A7%D8%B1-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA DA86D8A7D988D8AFD8A7D8B1 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>， <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d9%be%db%8c%d8%a7%d8%b2%da%86%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори ҳосили пиёзча дар гектар: Раҳнамои комил + Нуқтаҳои зиёдшавӣ</a></p>','Хатоги ва бемории ҷавондор бо об шӯрӣ: Роҳнамои мукаммали идора ва пешгирии хатоги','Гандум дар системҳои орошӣ қатрагӣ ва тасмавии тибр дар рӯ ба рӯ шудан бо мушкилоти махсус ба патогенҳо ва ҳашараҳо рӯбарӯ мешавад. Ин мақола ба таҳлили дақиқ механизмҳои паҳш кардани бемориҳо дар шароити намӣи маҳаллӣ баланди интишор ва пешниҳод кардани роҳҳои ягона барои идоракунии устувори зарари ҳашараҳо ва бемориҳо ишора мекунад.','publish','closed','closed','xatoghi-va-bemorih-javonbor-obshuri-rahnomo',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
